import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.IntSummaryStatistics;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Main {
    record Order(String user, String category, int amount) {}

    public static void main(String[] args) throws IOException {
        List<Order> orders = List.of(
            new Order("Ada", "book", 120),
            new Order("Bob", "game", 200),
            new Order("Ada", "book", 80),
            new Order("Cara", "book", 50),
            new Order("Bob", "tool", 30)
        );

        List<String> vipUsers = orders.stream()
            .filter(o -> o.amount() >= 100)
            .map(Order::user)
            .distinct()
            .sorted()
            .toList();
        System.out.println("vip users: " + vipUsers);

        boolean immutable = false;
        try {
            vipUsers.add("Zed");
        } catch (UnsupportedOperationException e) {
            immutable = true;
        }

        Map<String, Integer> totalByUser = orders.stream().collect(
            Collectors.toMap(Order::user, Order::amount, Integer::sum, TreeMap::new)
        );
        System.out.println("total by user: " + totalByUser);

        Map<String, IntSummaryStatistics> statsByCategory = orders.stream().collect(
            Collectors.groupingBy(Order::category, TreeMap::new, Collectors.summarizingInt(Order::amount))
        );
        System.out.println("book count/sum: " + statsByCategory.get("book").getCount() + "/" + statsByCategory.get("book").getSum());

        AtomicInteger touched = new AtomicInteger();
        Stream<Order> lazyPipeline = orders.stream().peek(o -> touched.incrementAndGet()).filter(o -> o.amount() > 100);
        assert touched.get() == 0;
        long expensiveCount = lazyPipeline.count();
        System.out.println("after terminal touched/count: " + touched.get() + "/" + expensiveCount);

        boolean consumedThrows = false;
        try {
            lazyPipeline.count();
        } catch (IllegalStateException e) {
            consumedThrows = true;
        }

        AtomicInteger visited = new AtomicInteger();
        Optional<String> firstBig = orders.stream()
            .filter(o -> {
                visited.incrementAndGet();
                return o.amount() > 100;
            })
            .map(Order::user)
            .findFirst();
        System.out.println("first big/visited: " + firstBig.orElse("none") + "/" + visited.get());

        int parallelSum = orders.parallelStream().mapToInt(Order::amount).sum();
        System.out.println("parallel sum: " + parallelSum);

        Path temp = Files.createTempFile("stream-api", ".txt");
        Files.write(temp, List.of("a", "bb", "ccc"));
        int lengthSum;
        try (Stream<String> lines = Files.lines(temp)) {
            lengthSum = lines.mapToInt(String::length).sum();
        }
        Files.deleteIfExists(temp);
        System.out.println("file length sum: " + lengthSum);

        assert vipUsers.equals(List.of("Ada", "Bob"));
        assert immutable;
        assert totalByUser.equals(Map.of("Ada", 200, "Bob", 230, "Cara", 50));
        assert statsByCategory.get("book").getCount() == 3;
        assert statsByCategory.get("book").getSum() == 250;
        assert touched.get() == orders.size();
        assert expensiveCount == 2;
        assert consumedThrows;
        assert firstBig.orElseThrow().equals("Ada");
        assert visited.get() == 1;
        assert parallelSum == 480;
        assert lengthSum == 6;
    }
}
